def cell_to_pos(cell):
    return (cell // 6, cell % 6)

def pos_to_cell(row, col):
    return row * 6 + col

def knight_moves(cell):
    row, col = cell_to_pos(cell)
    moves = []
    for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
        nr, nc = row + dr, col + dc
        if 0 <= nr < 6 and 0 <= nc < 6:
            moves.append(pos_to_cell(nr, nc))
    return moves

# Precompute knight moves for all cells
adj = {i: knight_moves(i) for i in range(36)}

# Fixed assignments: x[step] = cell
fixed = {
    0: 0,
    3: 17,
    6: 24,
    17: 30,
    19: 6,
    29: 25,
    32: 21,
    34: 23
}

# Build reverse mapping: cell -> step (for fixed cells)
fixed_cell_to_step = {v: k for k, v in fixed.items()}

# Backtracking solver
def solve():
    # x[step] = cell
    x = [None] * 36
    # visited[cell] = True/False
    visited = [False] * 36

    # Set fixed values
    for step, cell in fixed.items():
        x[step] = cell
        visited[cell] = True

    def backtrack(step):
        if step == 36:
            return True

        if x[step] is not None:
            # Fixed value, just check it's reachable from previous
            if step > 0:
                prev_cell = x[step - 1]
                if x[step] not in adj[prev_cell]:
                    return False
            return backtrack(step + 1)

        # Try all possible cells for this step
        prev_cell = x[step - 1]
        for cell in adj[prev_cell]:
            if not visited[cell]:
                # Check if this cell is fixed for a different step
                if cell in fixed_cell_to_step and fixed_cell_to_step[cell] != step:
                    continue

                x[step] = cell
                visited[cell] = True

                if backtrack(step + 1):
                    return True

                x[step] = None
                visited[cell] = False

        return False

    if backtrack(1):
        return x
    return None

result = solve()
if result:
    print("Solution found!")
    print(result)
    # Verify
    for i in range(35):
        if result[i+1] not in adj[result[i]]:
            print(f"ERROR: {result[i]} -> {result[i+1]} is not a valid knight move")
            break
    else:
        print("All moves valid!")
    print(f"Starts at {result[0]}, ends at {result[35]}")
    print(f"Visits {len(set(result))} unique cells")
else:
    print("No solution found")
